from collections.abc import Callable

Profile = dict[str, str]
Loader = Callable[[str, str], Profile]
Cache = dict[str, Profile]


def load_profile(cache: Cache, tenant_id: str, user_id: str, loader: Loader) -> Profile:
    key = f"profile:{user_id}"
    if key not in cache:
        cache[key] = loader(tenant_id, user_id)
    return cache[key]

import unittest

from profiles import load_profile


class ProfileTests(unittest.TestCase):
    def test_reuses_a_cached_profile(self) -> None:
        cache = {}
        loads = []

        def loader(tenant: str, user: str) -> dict[str, str]:
            loads.append((tenant, user))
            return {"id": user, "tenant": tenant}

        first = load_profile(cache, "tenant-a", "user-1", loader)
        second = load_profile(cache, "tenant-a", "user-1", loader)

        self.assertEqual(first, {"id": "user-1", "tenant": "tenant-a"})
        self.assertIs(second, first)
        self.assertEqual(loads, [("tenant-a", "user-1")])


if __name__ == "__main__":
    unittest.main()
